<span class="line has-focus"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">          &quot;downlinkCapacity&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">20</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
